/**
 * Collectable characters. Generated by scripts/import-depth-art.mjs from
 * design/depth/characters/characters.json; do not edit by hand. Saves store
 * the ids, so keep them stable once shipped.
 */

export interface Character {
  id: string;
  name: string;
  blurb: string;
  /** The chapter whose map they stand on. */
  homeChapter: number;
  /** Coins in the shop; 0 for gift characters, which are never sold. */
  price: number;
}

/** Given in this order on day 7 of the daily gift. Never random. */
export const GIFT_CHARACTERS: Character[] = [
  { id: 'potter', name: 'Poppy the Potter', blurb: 'Keeps the village wheel turning and always has a fresh pot in hand.', homeChapter: 1, price: 0 },
  { id: 'dog', name: 'Biscuit the Dog', blurb: 'A friendly meadow dog who guards the kiln and fetches stray tiles.', homeChapter: 1, price: 0 },
  { id: 'duck', name: 'Puddle the Duck', blurb: 'Paddles along the creek and quacks when a block slides home.', homeChapter: 2, price: 0 },
  { id: 'scarecrow', name: 'Scruff the Scarecrow', blurb: 'Keeps watch over the sunflowers, with a crow friend on one arm.', homeChapter: 3, price: 0 },
  { id: 'cat', name: 'Marmalade the Cat', blurb: 'A market-square cat who naps on warm cobbles and watches every move.', homeChapter: 4, price: 0 },
  { id: 'kilnmaster', name: 'Old Ember the Kiln Master', blurb: 'Sooty, proud and patient, he has fired every glaze at the Great Kiln.', homeChapter: 10, price: 0 },
];

/** Bought with coins in the shop. */
export const SHOP_CHARACTERS: Character[] = [
  { id: 'stallholder', name: 'Mabel the Stallholder', blurb: 'Sells apples and chatter from a striped stall in Market Town.', homeChapter: 4, price: 120 },
  { id: 'koala', name: 'Gumnut the Koala', blurb: 'Dozes on a gum branch and wakes only for a very good puzzle.', homeChapter: 6, price: 140 },
  { id: 'ferrycaptain', name: 'Captain Brine', blurb: 'Runs the ferry off Seaside Pier and keeps a lifebuoy handy.', homeChapter: 5, price: 160 },
  { id: 'snowgoat', name: 'Flurry the Snow-goat', blurb: 'A scarfed mountain goat who hops the icy ledges of Snowy Peaks.', homeChapter: 8, price: 180 },
  { id: 'lanternkeeper', name: 'Wick the Lantern Keeper', blurb: 'Lights every lantern in the garden at dusk, one pole at a time.', homeChapter: 7, price: 200 },
  { id: 'cameltrader', name: 'Dune the Camel Trader', blurb: 'Hauls glass and bright rugs across the desert with a patient smile.', homeChapter: 9, price: 250 },
];

export const CHARACTERS: Character[] = [...GIFT_CHARACTERS, ...SHOP_CHARACTERS];

/** The next gift character not yet owned, or null when all are owned. */
export function nextGiftCharacter(owned: string[]): Character | null {
  return GIFT_CHARACTERS.find((c) => !owned.includes(c.id)) ?? null;
}

export function characterById(id: string): Character | undefined {
  return CHARACTERS.find((c) => c.id === id);
}

/** The small figure that stands on a chapter map. */
export function characterMapUrl(id: string): string {
  return `${import.meta.env.BASE_URL}depth/char-${id}-map.svg`;
}

/** The larger figure that keeps the player company beside the board. */
export function characterSideUrl(id: string): string {
  return `${import.meta.env.BASE_URL}depth/char-${id}-side.svg`;
}
